bsc-confine() { local root="${BSC_REPO_ROOT:-}"; [ -z "$root" ] && return 0; local j fp rel; j="$(cat)"; fp="$(printf '%s' "$j" | __bsc_jstr 'file_path|notebook_path')"; [ -z "$fp" ] && return 0; fp="${fp//\\//}"; fp="$(printf '%s' "$fp" | tr -s '/')"; rel="${fp#"$root"/}"; rel="${rel#./}"; case "$rel" in .claude|.claude/*) __bsc_perm confine "$fp" "config-protection (.claude)"; echo "blocked: '$fp' is the session's .claude config — #1916 config-protection" >&2; return 2 ;; esac; case "$fp" in ..|../*|*/../*|*/..) __bsc_perm confine "$fp" "leaves the repo root"; echo "blocked: '$fp' leaves the repo root ($root) — #158 FS confinement" >&2; return 2 ;; esac; case "$fp" in /*|~*|[A-Za-z]:*) case "$fp" in "$root"|"$root"/*) return 0 ;; *) __bsc_perm confine "$fp" "outside the repo root"; echo "blocked: '$fp' is outside the repo root ($root) — #158 FS confinement" >&2; return 2 ;; esac ;; esac; return 0; }
